            mod: function(e) {
                if (_num.length - e.getLength() < 0) return this;
                var ratio = QRMath.glog(_num[0]) - QRMath.glog(e.getAt(0));
                var res = new Array(_num.length);
                for (var i = 0; i < _num.length; i += 1) res[i] = _num[i];
                for (var j = 0; j < e.getLength(); j += 1) {
                    res[j] ^= QRMath.gexp(QRMath.glog(e.getAt(j)) + ratio);
                }
                return qrPolynomial(res, 0).mod(e);
            }
