                        for (var c = -1; c <= 1; c += 1) {
                            if (col + c < 0 || moduleCount <= col + c || (r === 0 && c === 0)) continue;
                            if (dark === qrcode.isDark(row + r, col + c)) sameCount += 1;
                        }
